//! CPython builtins that the ported nltk code calls.
//!
//! These are not nltk items. They reproduce the CPython 3.11 behaviour (Unicode
//! 14.0.0 database) that the ported code depends on, so that the port does not
//! pick up the different Unicode version of the Rust standard library. The
//! tables are generated by `parity/gen_data.py`.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Deserialize)]
struct StrTables {
  isdigit: Vec<(u32, u32)>,
  isspace: Vec<(u32, u32)>,
  decimal_zeros: Vec<u32>,
  lower: Vec<(u32, String)>,
  case_ignorable: Vec<(u32, u32)>,
  cased: Vec<(u32, u32)>,
}

fn tables() -> &'static StrTables {
  static TABLES: OnceLock<StrTables> = OnceLock::new();
  TABLES.get_or_init(|| {
    serde_json::from_str(include_str!("../data/python_str.json"))
      .expect("data/python_str.json is valid")
  })
}

fn in_ranges(ranges: &[(u32, u32)], c: char) -> bool {
  let c = c as u32;
  ranges
    .binary_search_by(|&(lo, hi)| {
      if hi < c {
        std::cmp::Ordering::Less
      } else if lo > c {
        std::cmp::Ordering::Greater
      } else {
        std::cmp::Ordering::Equal
      }
    })
    .is_ok()
}

/// Port of CPython `str.isdigit` for a single character (Numeric_Type is
/// Digit or Decimal).
pub fn char_isdigit(c: char) -> bool {
  in_ranges(&tables().isdigit, c)
}

/// Port of CPython `str.isdigit`: true when the string is non-empty and every
/// character is a digit.
pub fn isdigit(s: &str) -> bool {
  !s.is_empty() && s.chars().all(char_isdigit)
}

/// Port of CPython `str.isspace` for a single character.
pub fn char_isspace(c: char) -> bool {
  in_ranges(&tables().isspace, c)
}

/// Port of CPython `unicodedata.decimal(c, -1)`: the decimal digit value of
/// `c`, if it has one.
pub fn decimal(c: char) -> Option<u32> {
  let zeros = &tables().decimal_zeros;
  let c = c as u32;
  let i = zeros.partition_point(|&z| z <= c);
  if i == 0 {
    return None;
  }
  let d = c - zeros[i - 1];
  (d < 10).then_some(d)
}

fn lower_map() -> &'static HashMap<u32, String> {
  static MAP: OnceLock<HashMap<u32, String>> = OnceLock::new();
  MAP.get_or_init(|| tables().lower.iter().cloned().collect())
}

/// Port of CPython `str.lower` (`unicodeobject.c` `do_lower`).
///
/// Applies the full lowercase mapping of CPython's Unicode 14.0.0 database,
/// and maps U+03A3 to final sigma U+03C2 in the Final_Sigma context
/// (`handle_capital_sigma`).
pub fn lower(s: &str) -> String {
  let chars: Vec<char> = s.chars().collect();
  let t = tables();
  let case_ignorable = |c: char| in_ranges(&t.case_ignorable, c);
  let cased = |c: char| in_ranges(&t.cased, c);
  let mut out = String::with_capacity(s.len());
  for (i, &c) in chars.iter().enumerate() {
    if c == '\u{3a3}' {
      // \p{cased}\p{case-ignorable}*U+03A3!(\p{case-ignorable}*\p{cased})
      let before = chars[..i].iter().rev().find(|&&c| !case_ignorable(c));
      let mut final_sigma = before.is_some_and(|&c| cased(c));
      if final_sigma && i + 1 < chars.len() {
        let after = chars[i + 1..].iter().find(|&&c| !case_ignorable(c));
        final_sigma = after.is_none_or(|&c| !cased(c));
      }
      out.push(if final_sigma { '\u{3c2}' } else { '\u{3c3}' });
    } else if let Some(l) = lower_map().get(&(c as u32)) {
      out.push_str(l);
    } else {
      out.push(c);
    }
  }
  out
}

/// The result of CPython `int(text, base)`.
///
/// Values that do not fit in an `i64` saturate. The callers only pass the value
/// to `chr`, which rejects every value outside `0..=0x10FFFF` with the same
/// outcome.
pub type PyInt = Result<i64, ValueError>;

/// CPython `ValueError`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ValueError;

/// Port of CPython `int(text, base)` for `base` 10 or 16
/// (`PyLong_FromUnicodeObject` and `PyLong_FromString`).
///
/// Follows CPython: non-ASCII whitespace becomes a space and Unicode decimal
/// digits become ASCII digits first, then leading and trailing ASCII
/// whitespace, an optional sign, an optional `0x` prefix (base 16) followed by
/// one optional underscore, and single underscores between digits are
/// accepted. Base 10 strings longer than 4300 digits raise `ValueError`
/// (`sys.get_int_max_str_digits()`).
pub fn int(text: &str, base: u32) -> PyInt {
  assert!(base == 10 || base == 16, "only bases 10 and 16 are ported");
  // _PyUnicode_TransformDecimalAndSpaceToASCII
  let mut buf: Vec<u8> = Vec::with_capacity(text.len());
  for ch in text.chars() {
    if (ch as u32) < 127 {
      buf.push(ch as u8);
    } else if char_isspace(ch) {
      buf.push(b' ');
    } else if let Some(d) = decimal(ch) {
      buf.push(b'0' + d as u8);
    } else {
      buf.push(b'?');
      break;
    }
  }
  let is_space = |b: u8| matches!(b, b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r');
  let mut i = 0;
  while i < buf.len() && is_space(buf[i]) {
    i += 1;
  }
  let mut negative = false;
  if i < buf.len() && buf[i] == b'+' {
    i += 1;
  } else if i < buf.len() && buf[i] == b'-' {
    i += 1;
    negative = true;
  }
  if base == 16 && i + 1 < buf.len() && buf[i] == b'0' && (buf[i + 1] == b'x' || buf[i + 1] == b'X')
  {
    i += 2;
    if i < buf.len() && buf[i] == b'_' {
      i += 1;
    }
  }
  if i < buf.len() && buf[i] == b'_' {
    return Err(ValueError);
  }
  let digit = |b: u8| -> Option<u32> { (b as char).to_digit(base) };
  let mut value: i64 = 0;
  let mut ndigits = 0usize;
  let mut prev_underscore = false;
  while i < buf.len() {
    let b = buf[i];
    if b == b'_' {
      if prev_underscore {
        return Err(ValueError);
      }
      prev_underscore = true;
    } else if let Some(d) = digit(b) {
      prev_underscore = false;
      ndigits += 1;
      value = value
        .saturating_mul(i64::from(base))
        .saturating_add(i64::from(d));
    } else {
      break;
    }
    i += 1;
  }
  if prev_underscore || ndigits == 0 {
    return Err(ValueError);
  }
  while i < buf.len() && is_space(buf[i]) {
    i += 1;
  }
  if i != buf.len() {
    return Err(ValueError);
  }
  if base == 10 && ndigits > 4300 {
    return Err(ValueError);
  }
  Ok(if negative { -value } else { value })
}

/// Port of CPython `bytes((number,)).decode("cp1252")` for `0x80..=0x9F`.
///
/// Returns `None` for the five bytes that cp1252 leaves undefined (CPython
/// raises `UnicodeDecodeError`).
pub fn cp1252_c1(number: u8) -> Option<char> {
  const TABLE: [u32; 32] = [
    0x20ac, 0, 0x201a, 0x192, 0x201e, 0x2026, 0x2020, 0x2021, 0x2c6, 0x2030, 0x160, 0x2039, 0x152,
    0, 0x17d, 0, 0, 0x2018, 0x2019, 0x201c, 0x201d, 0x2022, 0x2013, 0x2014, 0x2dc, 0x2122, 0x161,
    0x203a, 0x153, 0, 0x17e, 0x178,
  ];
  let cp = *TABLE.get(usize::from(number.checked_sub(0x80)?))?;
  if cp == 0 { None } else { char::from_u32(cp) }
}

/// Port of `html.entities.name2codepoint` (the 252 HTML 4 entity names).
pub fn name2codepoint() -> &'static HashMap<String, u32> {
  static MAP: OnceLock<HashMap<String, u32>> = OnceLock::new();
  MAP.get_or_init(|| {
    serde_json::from_str(include_str!("../data/html_name2codepoint.json"))
      .expect("data/html_name2codepoint.json is valid")
  })
}
